```c
monitor BoundedBuffer {
    Condition notFull, notEmpty;
    int count = 0;

    procedure produce(Item item) {
        while (count == BUFFER_SIZE)
            notFull.wait();

        buffer[in] = item;
        in = (in + 1) % BUFFER_SIZE;
        count++;

        notEmpty.signal();
    }
}
```

