def find_words(s, words):
    occurrence_indices = []
    for word in words:
        start = 0
        while True:
            index = s.find(word, start)
            if index == -1:
                break
            else:
                occurrence_indices.append(index)
                start = index + 1
    return occurrence_indices
```

